    10→/**
    11→ * Trading Layout
    12→ *
    13→ * Issue #81 - Réorganisation sidebar Trading:
    14→ * - Nouvelle structure par intention (MY FEED, DISCOVER, MY TRADING, PUBLISH, INSIGHTS & GROWTH)
    15→ * - Badges dynamiques selon plan utilisateur
    16→ * - Compteur de signaux actifs suivis
    17→ * - État des sections persiste dans localStorage
    18→ *
    19→ * Layout pour l'espace Trading avec sidebar dédiée
    20→ * Contient: Dashboard, Signals, Traders, Pricing, Checkout
    21→ * Sidebar conditionnelle selon le rôle (trader ou consumer)
    22→ */
    23→export default async function TradingLayout({ children }: PropsWithChildren) {
    24→  const user = await getRequiredUser();
    25→
    26→  // Check if user has trader profile (for conditional PUBLISH section)
    27→  const hasTraderProfile = await checkUserHasTraderProfile(user.id);
    28→
    29→  // Get user plan for badges
