    42→          allLinks={allLinks}
    43→          hasTraderProfile={hasTraderProfile}
    44→          activeSignalsCount={activeSignalsCount}
    45→          userPlan={userPlan}
    46→        />
    47→      }
    48→    >
    49→      {children}
    50→    </BaseSidebarLayout>
    51→  );
    52→}
