   137→  const state = open ? "expanded" : "collapsed";
   138→
   139→  const contextValue = React.useMemo<SidebarContextProps>(
   140→    () => ({
   141→      state,
   142→      open,
   143→      setOpen,
   144→      isMobile,
   145→      openMobile,
   146→      setOpenMobile,
   147→      toggleSidebar,
   148→    }),
   149→    [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar],
   150→  );
   151→
   152→  return (
   153→    <SidebarContext.Provider value={contextValue}>
   154→      <TooltipProvider delayDuration={0}>
   155→        <div
   156→          data-slot="sidebar-wrapper"
   157→          style={
   158→            {
   159→              "--sidebar-width": SIDEBAR_WIDTH,
   160→              "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
   161→              ...style,
   162→            } as React.CSSProperties
   163→          }
   164→          className={cn(
   165→            "group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full",
   166→            className,
   167→          )}
   168→          {...props}
   169→        >
   170→          {children}
   171→        </div>
   172→      </TooltipProvider>
   173→    </SidebarContext.Provider>
   174→  );
   175→}
