    72→type PaymentStatus = "pending" | "confirmed" | "expired";
    73→
    74→export const CheckoutForm = ({
    75→  plan,
    76→  isTestnet = false,
    77→}: CheckoutFormProps) => {
    78→  const router = useRouter();
    79→  const planData = MYCRYPTOPILOT_PLANS.find((p) => p.name === plan);
    80→
    81→  if (!planData) {
    82→    throw new Error(`Plan ${plan} not found`);
    83→  }
    84→
    85→  const [addresses, setAddresses] = useState<GeneratedAddresses | null>(null);
    86→  const [expiresAt, setExpiresAt] = useState<Date | null>(null);
    87→  const [paymentStatus, setPaymentStatus] = useState<PaymentStatus>("pending");
    88→  const [qrCodes, setQrCodes] = useState<{
    89→    base: string;
    90→    tron: string;
