    92→  const [showTestSuccessDialog, setShowTestSuccessDialog] = useState(false);
    93→
    94→  // Generate crypto addresses on mount
    95→  const generateMutation = useMutation({
    96→    mutationFn: async () => {
    97→      const result = await generateAddressAction({
    98→        plan: plan as "test" | "pro" | "ultra",
    99→      });
   100→
   101→      if (!isActionSuccessful(result)) {
   102→        throw new Error(result.serverError ?? "Failed to generate addresses");
   103→      }
   104→
   105→      return result.data;
   106→    },
   107→    onSuccess: async (data) => {
   108→      setAddresses(data.addresses);
   109→      setExpiresAt(new Date(data.expiresAt));
   110→
   111→      // Generate QR codes
   112→      try {
   113→        const [baseQR, tronQR] = await Promise.all([
   114→          QRCode.toDataURL(data.addresses.base.address, { width: 256 }),
   115→          QRCode.toDataURL(data.addresses.tron.address, { width: 256 }),
   116→        ]);
   117→        setQrCodes({ base: baseQR, tron: tronQR });
   118→      } catch (error) {
